CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', timezone text NOT NULL DEFAULT 'America/Sao_Paulo', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.private_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND (NOT public.has_role(auth.uid(),'admin') OR (auth.jwt()->>'aal')='aal2') $$;
REVOKE ALL ON FUNCTION public.private_access() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.private_access() TO authenticated,service_role;
CREATE POLICY profile_edit ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid() AND public.private_access()) WITH CHECK(id=auth.uid() AND public.private_access());
CREATE TABLE public.settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', products_per_day integer NOT NULL DEFAULT 3, daily_post_limit integer NOT NULL DEFAULT 6, window_start time NOT NULL DEFAULT '08:00', window_end time NOT NULL DEFAULT '22:00', min_interval_minutes integer NOT NULL DEFAULT 45, story_delay_min_hours integer NOT NULL DEFAULT 1, story_delay_max_hours integer NOT NULL DEFAULT 8, warmup_initial_days integer NOT NULL DEFAULT 3, warmup_initial_limit integer NOT NULL DEFAULT 1, warmup_second_end_day integer NOT NULL DEFAULT 7, warmup_second_limit integer NOT NULL DEFAULT 2, repeat_days integer NOT NULL DEFAULT 14, max_attempts integer NOT NULL DEFAULT 3, min_images integer NOT NULL DEFAULT 3, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.settings TO authenticated; GRANT ALL ON public.settings TO service_role; ALTER TABLE public.settings ENABLE ROW LEVEL SECURITY; CREATE POLICY settings_owner ON public.settings FOR ALL TO authenticated USING(user_id=auth.uid() AND public.private_access()) WITH CHECK(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.connector_secrets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ciphertext text NOT NULL, key_version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.connector_secrets TO service_role; ALTER TABLE public.connector_secrets ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.marketplace_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, marketplace text NOT NULL DEFAULT 'shopee', status text NOT NULL DEFAULT 'disconnected', credential_id uuid REFERENCES public.connector_secrets(id), last_synced_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT ON public.marketplace_connections TO authenticated; GRANT ALL ON public.marketplace_connections TO service_role; ALTER TABLE public.marketplace_connections ENABLE ROW LEVEL SECURITY; CREATE POLICY connections_read ON public.marketplace_connections FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.instagram_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, ig_user_id text, username text, page_id text, credential_id uuid REFERENCES public.connector_secrets(id), token_expires_at timestamptz, status text NOT NULL DEFAULT 'disconnected', daily_limit integer NOT NULL DEFAULT 6, warmup_started_at timestamptz, timezone text NOT NULL DEFAULT 'America/Sao_Paulo', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id));
GRANT SELECT ON public.instagram_accounts TO authenticated; GRANT ALL ON public.instagram_accounts TO service_role; ALTER TABLE public.instagram_accounts ENABLE ROW LEVEL SECURITY; CREATE POLICY instagram_read ON public.instagram_accounts FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.search_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, instagram_account_id uuid, name text NOT NULL, filters jsonb NOT NULL DEFAULT '{}', mode text NOT NULL DEFAULT 'manual', posts_per_day integer NOT NULL DEFAULT 3, windows jsonb NOT NULL DEFAULT '[{"start":"08:00","end":"22:00"}]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(instagram_account_id,user_id) REFERENCES public.instagram_accounts(id,user_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.search_profiles TO authenticated; GRANT ALL ON public.search_profiles TO service_role; ALTER TABLE public.search_profiles ENABLE ROW LEVEL SECURITY; CREATE POLICY search_owner ON public.search_profiles FOR ALL TO authenticated USING(user_id=auth.uid() AND public.private_access()) WITH CHECK(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, marketplace text NOT NULL DEFAULT 'shopee', external_id text NOT NULL, title text NOT NULL, price numeric(14,2), commission numeric(14,4), sales bigint, rating numeric(3,2), category text, images jsonb NOT NULL DEFAULT '[]', url text, collected_at timestamptz NOT NULL DEFAULT now(), click_score numeric, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), UNIQUE(user_id,marketplace,external_id));
GRANT SELECT ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY products_read ON public.products FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.video_assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, instagram_account_id uuid, storage_path text, duration_seconds numeric, provider_job_id text, template text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(instagram_account_id,user_id) REFERENCES public.instagram_accounts(id,user_id));
GRANT SELECT ON public.video_assets TO authenticated; GRANT ALL ON public.video_assets TO service_role; ALTER TABLE public.video_assets ENABLE ROW LEVEL SECURITY; CREATE POLICY videos_read ON public.video_assets FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, instagram_account_id uuid NOT NULL, product_id uuid NOT NULL, search_profile_id uuid, format text NOT NULL DEFAULT 'reel', status text NOT NULL DEFAULT 'draft', scheduled_at timestamptz, published_at timestamptz, video_asset_id uuid, caption text, trigger_word text, affiliate_link text, sub_id text, ig_media_id text, parent_post_id uuid, attempts integer NOT NULL DEFAULT 0, error text, idempotency_key uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(instagram_account_id,user_id) REFERENCES public.instagram_accounts(id,user_id), FOREIGN KEY(product_id,user_id) REFERENCES public.products(id,user_id), FOREIGN KEY(search_profile_id,user_id) REFERENCES public.search_profiles(id,user_id), FOREIGN KEY(video_asset_id,user_id) REFERENCES public.video_assets(id,user_id), FOREIGN KEY(parent_post_id,user_id) REFERENCES public.posts(id,user_id));
GRANT SELECT ON public.posts TO authenticated; GRANT ALL ON public.posts TO service_role; ALTER TABLE public.posts ENABLE ROW LEVEL SECURITY; CREATE POLICY posts_read ON public.posts FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.comment_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, post_id uuid NOT NULL, comment_id text NOT NULL UNIQUE, author_id text, status text NOT NULL DEFAULT 'detected', sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(post_id,user_id) REFERENCES public.posts(id,user_id));
GRANT SELECT ON public.comment_events TO authenticated; GRANT ALL ON public.comment_events TO service_role; ALTER TABLE public.comment_events ENABLE ROW LEVEL SECURITY; CREATE POLICY comments_read ON public.comment_events FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.bio_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, instagram_account_id uuid NOT NULL, slug text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(instagram_account_id,user_id) REFERENCES public.instagram_accounts(id,user_id));
GRANT SELECT ON public.bio_pages TO authenticated; GRANT ALL ON public.bio_pages TO service_role; ALTER TABLE public.bio_pages ENABLE ROW LEVEL SECURITY; CREATE POLICY bio_read ON public.bio_pages FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.bio_links (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, bio_page_id uuid NOT NULL, post_id uuid NOT NULL, product_id uuid NOT NULL, position integer NOT NULL DEFAULT 0, visible boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,user_id), FOREIGN KEY(bio_page_id,user_id) REFERENCES public.bio_pages(id,user_id), FOREIGN KEY(post_id,user_id) REFERENCES public.posts(id,user_id), FOREIGN KEY(product_id,user_id) REFERENCES public.products(id,user_id));
GRANT SELECT ON public.bio_links TO authenticated; GRANT ALL ON public.bio_links TO service_role; ALTER TABLE public.bio_links ENABLE ROW LEVEL SECURITY; CREATE POLICY biolinks_read ON public.bio_links FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.click_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, bio_link_id uuid NOT NULL, post_id uuid NOT NULL, user_agent_hash text, is_bot boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(bio_link_id,user_id) REFERENCES public.bio_links(id,user_id), FOREIGN KEY(post_id,user_id) REFERENCES public.posts(id,user_id));
GRANT SELECT ON public.click_events TO authenticated; GRANT ALL ON public.click_events TO service_role; ALTER TABLE public.click_events ENABLE ROW LEVEL SECURITY; CREATE POLICY clicks_read ON public.click_events FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, external_order_id text NOT NULL, sub_id text, status text NOT NULL DEFAULT 'pending', commission numeric(14,2) NOT NULL DEFAULT 0, product_id uuid, post_id uuid, ordered_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,external_order_id), FOREIGN KEY(product_id,user_id) REFERENCES public.products(id,user_id), FOREIGN KEY(post_id,user_id) REFERENCES public.posts(id,user_id));
GRANT SELECT ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY orders_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.metrics_daily (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, day date NOT NULL, post_id uuid, product_id uuid, template text, clicks bigint NOT NULL DEFAULT 0, orders bigint NOT NULL DEFAULT 0, pending_commission numeric(14,2) NOT NULL DEFAULT 0, completed_commission numeric(14,2) NOT NULL DEFAULT 0, reach bigint, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(post_id,user_id) REFERENCES public.posts(id,user_id), FOREIGN KEY(product_id,user_id) REFERENCES public.products(id,user_id));
GRANT SELECT ON public.metrics_daily TO authenticated; GRANT ALL ON public.metrics_daily TO service_role; ALTER TABLE public.metrics_daily ENABLE ROW LEVEL SECURITY; CREATE POLICY metrics_read ON public.metrics_daily FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.activity_log (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, action text NOT NULL, result text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.activity_log TO authenticated; GRANT ALL ON public.activity_log TO service_role; ALTER TABLE public.activity_log ENABLE ROW LEVEL SECURITY; CREATE POLICY log_read ON public.activity_log FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, limits jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plans TO authenticated; GRANT ALL ON public.plans TO service_role; ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY; CREATE POLICY plans_read ON public.plans FOR SELECT TO authenticated USING(public.private_access());
CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, plan_id uuid REFERENCES public.plans(id), status text NOT NULL DEFAULT 'inactive', provider text, external_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role; ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscriptions_read ON public.subscriptions FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE TABLE public.entitlements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, name text NOT NULL, value jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.entitlements TO authenticated; GRANT ALL ON public.entitlements TO service_role; ALTER TABLE public.entitlements ENABLE ROW LEVEL SECURITY; CREATE POLICY entitlements_read ON public.entitlements FOR SELECT TO authenticated USING(user_id=auth.uid() AND public.private_access());
CREATE FUNCTION public.initialize_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE assigned_role public.app_role; BEGIN PERFORM pg_advisory_xact_lock(918374); assigned_role=CASE WHEN NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='admin') THEN 'admin'::public.app_role ELSE 'user'::public.app_role END; INSERT INTO public.profiles(id,name) VALUES(NEW.id,coalesce(NEW.raw_user_meta_data->>'name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,assigned_role); INSERT INTO public.settings(user_id) VALUES(NEW.id); INSERT INTO public.activity_log(user_id,action,result) VALUES(NEW.id,'Conta criada','Sucesso'); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.initialize_owner() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER initialize_divulga_owner AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.initialize_owner();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','user_roles','settings','connector_secrets','marketplace_connections','instagram_accounts','search_profiles','products','posts','video_assets','comment_events','bio_pages','bio_links','click_events','orders','metrics_daily','activity_log','plans','subscriptions','entitlements'] LOOP EXECUTE format('CREATE TRIGGER touch_updated BEFORE UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at()',t); IF t NOT IN ('profiles','plans') THEN EXECUTE format('CREATE INDEX ON public.%I(user_id)',t); END IF; END LOOP; END $$;
CREATE FUNCTION public.validate_settings() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=NEW.timezone) OR NEW.products_per_day NOT BETWEEN 1 AND 100 OR NEW.daily_post_limit NOT BETWEEN 1 AND 200 OR NEW.window_start>=NEW.window_end OR NEW.min_interval_minutes<1 OR NEW.story_delay_min_hours<1 OR NEW.story_delay_max_hours<NEW.story_delay_min_hours OR NEW.story_delay_max_hours>23 OR NEW.repeat_days<1 OR NEW.max_attempts NOT BETWEEN 1 AND 10 OR NEW.min_images<3 THEN RAISE EXCEPTION 'Configurações inválidas'; END IF; RETURN NEW; END $$;
CREATE TRIGGER settings_validation BEFORE INSERT OR UPDATE ON public.settings FOR EACH ROW EXECUTE FUNCTION public.validate_settings();